def transform(g):
    h,w=len(g),len(g[0])
    v=next(x for row in g for x in row if x)
    out=[row[:] for row in g]
    # collect lines: for each cell of v, if no cell of v up-left, start of down-left line etc.
    def start(r,c,dr,dc):  # line going direction (dr,dc); start has no v at (r-dr,c-dc)
        pr,pc=r-dr,c-dc
        return not(0<=pr<h and 0<=pc<w and g[pr][pc]==v)
    lines=[]  # (slope_sign, intercept c - sign*r)  dr=1, dc=+1 -> c-r; dc=-1 -> c+r
    for r in range(h):
        for c in range(w):
            if g[r][c]!=v: continue
            if start(r,c,1,1) and start(r,c,-1,-1):
                lines.append((1,c-r))
            if start(r,c,1,-1) and start(r,c,-1,1):
                lines.append((-1,c+r))
    for i,(s1,b1) in enumerate(lines):
        for s2,b2 in lines[i+1:]:
            if s1==s2: continue
            # c = s1*r + b1 (for s=1: c=r+b; s=-1: c=-r+b) -> s*r+b
            r=(b2-b1)/(s1-s2)
            c=s1*r+b1
            if not (0<=r<h and 0<=c<w and float(r).is_integer()): continue
            r=int(r)
            for rr in range(h):
                lo,hi=sorted((s1*rr+b1, s2*rr+b2))
                for cc in range(max(0,lo+1),min(w,hi)):
                    if out[rr][cc]==0: out[rr][cc]=2
    return out

